from rules import resolve


def solve(data):
    return resolve(data)

def resolve(data):
    packages = data.get("packages", {})
    roots = data.get("roots", {})
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    features = set(data.get("features", []))
    names = sorted(packages)

    constraints = {}
    for name, interval in roots.items():
        constraints.setdefault(name, []).append((interval[0], interval[1]))

    best_score = None
    best_versions = None

    def active_dependencies(row):
        for dep in row.get("deps", []):
            feature = dep.get("feature")
            if feature and feature not in features:
                continue
            yield dep

    def candidates(name, limits):
        if name not in packages:
            return []
        forbidden = blocked.get(name, [])
        pin = pins.get(name)
        return [
            row for row in packages[name]
            if all(lo <= row["version"] <= hi for lo, hi in limits)
            and row["version"] not in forbidden
            and (pin is None or row["version"] == pin)
        ]

    def is_acyclic(assigned):
        graph = {
            name: [dep["name"] for dep in active_dependencies(row)]
            for name, row in assigned.items()
        }
        state = {}

        def visit(name):
            mark = state.get(name, 0)
            if mark == 1:
                return False
            if mark == 2:
                return True
            state[name] = 1
            for target in graph.get(name, []):
                if target not in assigned or not visit(target):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in assigned)

    def search(assigned, required):
        nonlocal best_score, best_versions

        # Newly accumulated requirements must also hold for already chosen rows.
        for name, row in assigned.items():
            version = row["version"]
            if any(not (lo <= version <= hi) for lo, hi in required.get(name, [])):
                return
            if version in blocked.get(name, []):
                return
            if name in pins and version != pins[name]:
                return

        unresolved = [name for name in required if name not in assigned]
        if not unresolved:
            if not is_acyclic(assigned):
                return
            versions = {name: row["version"] for name, row in assigned.items()}
            score = tuple(versions.get(name, -1) for name in names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = versions
            return

        # Choose a constrained package first to prune incompatible branches.
        domains = [(candidates(name, required[name]), name) for name in unresolved]
        domain, name = min(domains, key=lambda item: (len(item[0]), item[1]))
        for row in domain:
            next_assigned = dict(assigned)
            next_assigned[name] = row
            next_required = {key: list(value) for key, value in required.items()}
            for dep in active_dependencies(row):
                next_required.setdefault(dep["name"], []).append((dep["min"], dep["max"]))
            search(next_assigned, next_required)

    search({}, constraints)
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}
